<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('withdrawals.view');$status=strtoupper((string)input('status'));$q=trim((string)input('q'));$from=trim((string)input('from'));$to=trim((string)input('to'));$valid=['PENDING','UNDER_REVIEW','APPROVED','PROCESSING','PAID','REJECTED','CANCELLED'];$page=page_int();[$limit,$offset]=pagination($page);$where=[];$params=[];if(in_array($status,$valid,true)){$where[]='w.status=?';$params[]=$status;}if($q!==''){$where[]='(w.withdrawal_id LIKE ? OR u.name LIKE ? OR u.mobile LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');}if($from!==''&&valid_date($from)){$where[]='w.requested_at>=?';$params[]=$from;}if($to!==''&&valid_date($to)){$where[]='w.requested_at<DATE_ADD(?,INTERVAL 1 DAY)';$params[]=$to;}$sqlWhere=$where?' WHERE '.implode(' AND ',$where):'';$count=db()->prepare('SELECT COUNT(*) FROM withdrawals w JOIN users u ON u.id=w.user_id'.$sqlWhere);$count->execute($params);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT w.*,u.name,u.mobile,wa.balance FROM withdrawals w JOIN users u ON u.id=w.user_id JOIN wallets wa ON wa.id=w.wallet_id'.$sqlWhere.' ORDER BY w.id DESC LIMIT '.$limit.' OFFSET '.$offset);$stmt->execute($params);$rows=$stmt->fetchAll();$pageTitle='Withdrawals';$pageSubtitle='Review risk and enforce controlled status transitions';require APP_ROOT.'/includes/header.php';?>
<section class="panel"><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Withdrawal, user or mobile"><select name="status"><option value="">All statuses</option><?php foreach($valid as $s):?><option <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach?></select><input type="date" name="from" value="<?=e($from)?>"><input type="date" name="to" value="<?=e($to)?>"><button class="btn">Filter</button></form><div class="table-wrap"><table><thead><tr><th>Withdrawal</th><th>User</th><th>Amount</th><th>Available</th><th>Method</th><th>Status</th><th>Risk</th><th>Requested</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['withdrawal_id'])?></strong></td><td><?=e($r['name'])?><br><small><?=e($r['mobile'])?></small></td><td><?=money($r['amount'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['payment_method'])?><br><small><?=e($r['payment_account_masked']??'—')?></small></td><td><span class="badge <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><span class="risk <?=strtolower(e($r['risk_level']))?>"><?=e($r['risk_level'])?></span></td><td><?=e($r['requested_at'])?></td><td><a class="btn small secondary" href="<?=e(app_url('/admin/withdrawals/view.php?id='.$r['id']))?>">Review</a></td></tr><?php endforeach?></tbody></table><?php if(!$rows):?><div class="empty">No withdrawals found.</div><?php endif?></div><div class="pagination"><?php for($i=1;$i<=ceil($total/$limit);$i++):?><a href="?<?=e(http_build_query(['q'=>$q,'status'=>$status,'from'=>$from,'to'=>$to,'page'=>$i]))?>"><?=$i?></a><?php endfor?></div></section><?php require APP_ROOT.'/includes/footer.php';

